from urllib.parse import parse_qsl, urlencode, urlparse, urlunparse


def apply_rewrite_rules(rules, urls):
    processed_urls = []

    for url in urls:
        parsed = urlparse(url)
        rewritten = False

        for rule in rules:
            match_type = rule.get("match_type")
            match_value = rule.get("match_value")
            action = rule.get("action")
            action_value = rule.get("action_value")

            matched = False

            # 1. Match type: host
            if match_type == "host":
                if match_value.startswith("*."):
                    suffix = match_value[1:]  # e.g., ".example.com"
                    if parsed.hostname and parsed.hostname.endswith(suffix):
                        # Ensure it's a strict subdomain, not the domain itself
                        if len(parsed.hostname) > len(suffix):
                            matched = True
                else:
                    if parsed.hostname == match_value:
                        matched = True

            # 2. Match type: path_prefix
            elif match_type == "path_prefix":
                if parsed.path.startswith(match_value):
                    matched = True

            # 3. Match type: query_param
            elif match_type == "query_param":
                query_params = parse_qsl(parsed.query, keep_blank_values=True)
                if any(k == match_value for k, v in query_params):
                    matched = True

            # If the rule matched, apply the action and stop checking rules for this URL
            if matched:
                if action == "block":
                    processed_urls.append(None)
                    rewritten = True
                    break

                elif action == "strip_prefix":
                    # Remove action_value from the start of the path
                    if parsed.path.startswith(action_value):
                        new_path = parsed.path[len(action_value) :]
                        if not new_path:
                            new_path = "/"
                    else:
                        new_path = parsed.path

                    parsed = parsed._replace(path=new_path)
                    processed_urls.append(urlunparse(parsed))
                    rewritten = True
                    break

                elif action == "redirect_host":
                    # Replace the host, preserving scheme, port, etc.
                    # Note: parsed.netloc includes auth/port if present, so we carefully rebuild netloc
                    old_netloc = parsed.netloc
                    if "@" in old_netloc:
                        auth = old_netloc.split("@")[0] + "@"
                    else:
                        auth = ""

                    if ":" in parsed.netloc and not parsed.netloc.endswith(
                        "]"
                    ):  # handles standard ports
                        port_part = ":" + parsed.netloc.split(":")[-1]
                    else:
                        port_part = ""

                    new_netloc = auth + action_value + port_part
                    parsed = parsed._replace(netloc=new_netloc)
                    processed_urls.append(urlunparse(parsed))
                    rewritten = True
                    break

                elif action == "add_query_param":
                    # action_value is expected to be like "key=value" or we can parse it
                    if "=" in action_value:
                        add_k, add_v = action_value.split("=", 1)
                    else:
                        add_k, add_v = action_value, ""

                    query_params = parse_qsl(parsed.query, keep_blank_values=True)
                    query_params.append((add_k, add_v))
                    new_query = urlencode(query_params)

                    parsed = parsed._replace(query=new_query)
                    processed_urls.append(urlunparse(parsed))
                    rewritten = True
                    break

        # If no rules matched, return the URL unchanged
        if not rewritten:
            processed_urls.append(url)

    return processed_urls
